import { useEffect, useState } from "react";
import axios from "axios";

export default function TeacherDashboard() {
  const [courses, setCourses] = useState([]);
  const [submissions, setSubmissions] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const courseRes = await axios.get("/api/teachers/1/courses");
      const subRes = await axios.get("/api/teachers/1/submissions");

      setCourses(courseRes.data);
      setSubmissions(subRes.data);
    } catch (err) {
      console.log(err);
    }
  };

  const totalStudents = courses.reduce(
    (sum, c) => sum + (c.student_count || 0),
    0
  );

  return (
    <div className="p-6">
      {/* HEADER */}
      <h1 className="text-2xl font-bold">Dr. Riya Sharma</h1>
      <p className="text-gray-500 mb-6">Teacher dashboard</p>

      {/* TOP STATS (SAME UI) */}
      <div className="flex gap-10 mb-6">
        <div>
          <p className="text-gray-500 text-sm">My courses</p>
          <h2 className="text-2xl font-bold">{courses.length}</h2>
        </div>

        <div>
          <p className="text-gray-500 text-sm">Total students</p>
          <h2 className="text-2xl font-bold">{totalStudents}</h2>
        </div>

        <div>
          <p className="text-gray-500 text-sm">Pending grading</p>
          <h2 className="text-2xl font-bold">{submissions.length}</h2>
        </div>
      </div>

      {/* CLASS PERFORMANCE (UNCHANGED UI BLOCK) */}
      <div className="bg-white p-5 rounded-lg shadow mb-6 border">
        <div className="flex justify-between mb-4">
          <h2 className="text-sm text-gray-500 uppercase">
            Class Performance
          </h2>
          <select className="border px-2 py-1 rounded text-sm">
            <option>ML101</option>
          </select>
        </div>

        {/* Dummy bars (same as before) */}
        <div className="flex items-end gap-6 h-40">
          <div className="bg-blue-500 w-10 h-[90%]"></div>
          <div className="bg-blue-500 w-10 h-[75%]"></div>
          <div className="bg-blue-500 w-10 h-[65%]"></div>
        </div>

        <div className="flex gap-6 mt-2 text-sm text-gray-600">
          <span>Supervised Learning</span>
          <span>Deep Learning</span>
          <span>Model Evaluation</span>
        </div>
      </div>

      {/* RECENT SUBMISSIONS (UNCHANGED UI) */}
      <div className="bg-white p-5 rounded-lg shadow border">
        <h2 className="text-sm text-gray-500 uppercase mb-4">
          Recent Submissions
        </h2>

        {submissions.length === 0 ? (
          <p className="text-gray-500">No submissions yet</p>
        ) : (
          submissions.slice(0, 6).map((s) => (
            <div
              key={s.submission_id}
              className="flex justify-between items-center py-2 border-b"
            >
              <div>
                <p className="font-medium">{s.student_name}</p>
                <p className="text-sm text-gray-500">
                  {s.assignment_title}
                </p>
              </div>

              {/* Grade circle (same UI style) */}
              <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-sm font-bold text-green-700">
                A
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
